import{_ as r,o as a,c as d,ag as e,j as o}from"./chunks/framework.DoUXNnsN.js";const y=JSON.parse('{"title":"工业通信","description":"","frontmatter":{"title":"工业通信","aliases":["工业通信全景","工业控制网络","工业协议地图","Industrial Communication"],"tags":["工业通信","总览"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/List_of_TCP_and_UDP_port_numbers","https://en.wikipedia.org/wiki/Modbus","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"70-工业通信与自动化/工业通信.md","filePath":"70-工业通信与自动化/工业通信.md"}'),i={name:"70-工业通信与自动化/工业通信.md"},l={style:{"overflow-x":"auto"}},h={role:"img","aria-label":"工业通信三层模型",viewBox:"0 0 900 430",width:"100%",style:{"min-width":"720px","max-width":"900px",display:"block",margin:"16px auto"},"font-size":"13"};function n(c,t,s,u,p,f){return a(),d("div",null,[t[1]||(t[1]=e('<blockquote class="callout-warn"><p>⚠ 待核对：本篇&quot;协议地图&quot;里各协议的一句话定位来自模型知识和维基百科，已对照 Modbus（502）、MQTT（1883）、OPC UA（4840）的端口；EtherNet/IP、S7、FINS 等端口号和&quot;你们工厂实际在用哪些协议&quot;没有逐项联网核实或现场确认，请以设备手册和厂里实际情况为准。</p></blockquote><blockquote><p>本篇是&quot;工业通信与自动化&quot;这个目录的<strong>总览</strong>。读完你应该能：说出车间里数据从传感器走到 MES 经过哪几层、每层常用什么协议；分清现场总线和工业以太网；拿到一台陌生设备，知道先问&quot;它说什么协议&quot;；并按照本篇的入门路径把本目录的词条一篇篇学下去。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>工业通信，就是让<strong>传感器、执行器、PLC、触摸屏、上位机、MES</strong> 这些工业设备和软件互相交换数据所用的**线路（物理层）和约定（协议）**的总称。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/80-电子制造业务/地图/ISA-95">ISA-95</a>：知道企业系统分 Level 0–4 五层，本篇的&quot;三层&quot;是它的简化版。</li><li><a href="/Encyclopedia/80-电子制造业务/地图/电子制造信息系统全景图">电子制造信息系统全景图</a>：知道 ERP、MES、设备分别在哪一层。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>（可选）：后面讲以太网类协议时会用到。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>一条 SMT 线上有印刷机、贴片机、回流焊炉、AOI 等十来台设备，来自不同国家的不同厂家。MES 想知道&quot;回流焊炉现在炉温多少&quot;&quot;贴片机贴了多少片&quot;&quot;有没有报警&quot;，就得从这些设备里<strong>取数据</strong>；想下发&quot;换线后用 B 产品的程序&quot;，就得向设备<strong>写数据</strong>。</p><p>问题是：每个厂家在历史上都发明过自己的接线和约定，互相听不懂。<strong>工业通信</strong>要回答的就是：线怎么接、电平怎么定、字节怎么排、谁先说话、出错怎么办。学会它，你才能把设备数据真正接进 MES，而不是靠人抄。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="三层模型-设备层、控制层、信息层" tabindex="-1">三层模型：设备层、控制层、信息层 <a class="header-anchor" href="#三层模型-设备层、控制层、信息层" aria-label="Permalink to &quot;三层模型：设备层、控制层、信息层&quot;">​</a></h3><p>把工厂里的通信想成一栋三层楼：</p><table tabindex="0"><thead><tr><th>层</th><th>对应 ISA-95</th><th>里面有什么</th><th>数据特点</th><th>常见通信方式</th></tr></thead><tbody><tr><td>设备层（现场层）</td><td>Level 0–1</td><td>传感器、执行器、变频器、仪表</td><td>小数据、要快、要稳</td><td>24V 开关量、4–20 mA 模拟量、RS-485、CAN、现场总线</td></tr><tr><td>控制层</td><td>Level 1–2</td><td>PLC、HMI、SCADA</td><td>周期性读写、毫秒到百毫秒级</td><td>工业以太网（Profinet、EtherNet/IP、Modbus TCP）、厂家私有协议</td></tr><tr><td>信息层</td><td>Level 3–4</td><td>MES、ERP、数据库、云</td><td>数据量大、不要求毫秒级、要安全和统一</td><td>OPC UA、MQTT、HTTP/REST、数据库接口、行业标准（SECS/GEM、IPC-CFX）</td></tr></tbody></table><p>一句话记忆：<strong>越靠近机器，越讲究实时和可靠；越靠近管理，越讲究统一和开放。</strong></p><h3 id="图-数据怎么往上走" tabindex="-1">图：数据怎么往上走 <a class="header-anchor" href="#图-数据怎么往上走" aria-label="Permalink to &quot;图：数据怎么往上走&quot;">​</a></h3>',15)),o("div",l,[(a(),d("svg",h,[...t[0]||(t[0]=[e('<title>工业通信三层模型</title><defs><marker id="ic-arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0,0 L8,4 L0,8 z" fill="currentColor"></path></marker></defs><rect x="10" y="10" width="880" height="120" rx="12" fill="#2563eb" fill-opacity=".07" stroke="#2563eb" stroke-opacity=".35"></rect><rect x="10" y="150" width="880" height="120" rx="12" fill="#7c3aed" fill-opacity=".07" stroke="#7c3aed" stroke-opacity=".35"></rect><rect x="10" y="290" width="880" height="130" rx="12" fill="#0d9488" fill-opacity=".07" stroke="#0d9488" stroke-opacity=".35"></rect><g fill="currentColor"><text x="26" y="38" font-size="15" font-weight="700">信息层</text><text x="26" y="57">MES / ERP</text><text x="26" y="178" font-size="15" font-weight="700">控制层</text><text x="26" y="197">PLC / HMI / SCADA</text><text x="26" y="318" font-size="15" font-weight="700">设备层</text><text x="26" y="337">传感器 / 执行器</text></g><g fill="#2563eb" fill-opacity=".16" stroke="#2563eb" stroke-opacity=".7"><rect x="180" y="30" width="150" height="50" rx="8"></rect><rect x="360" y="30" width="150" height="50" rx="8"></rect><rect x="540" y="30" width="150" height="50" rx="8"></rect><rect x="720" y="30" width="150" height="50" rx="8"></rect></g><g fill="currentColor" text-anchor="middle"><text x="255" y="60" font-weight="700">OPC UA</text><text x="435" y="60" font-weight="700">MQTT</text><text x="615" y="60" font-weight="700">SECS/GEM</text><text x="795" y="60" font-weight="700">IPC-CFX</text><text x="450" y="112" font-size="11" opacity=".75">统一、开放、跨厂家（以太网 / TCP-IP 之上）</text></g><g fill="#7c3aed" fill-opacity=".16" stroke="#7c3aed" stroke-opacity=".7"><rect x="180" y="170" width="150" height="50" rx="8"></rect><rect x="360" y="170" width="150" height="50" rx="8"></rect><rect x="540" y="170" width="150" height="50" rx="8"></rect><rect x="720" y="170" width="150" height="50" rx="8"></rect></g><g fill="currentColor" text-anchor="middle"><text x="255" y="200" font-weight="700">Modbus TCP</text><text x="435" y="200" font-weight="700">Profinet</text><text x="615" y="200" font-weight="700">EtherNet/IP</text><text x="795" y="200" font-weight="700">S7 / MC / FINS</text><text x="450" y="252" font-size="11" opacity=".75">工业以太网：快、可多设备并联、部分带实时能力</text></g><g fill="#0d9488" fill-opacity=".16" stroke="#0d9488" stroke-opacity=".7"><rect x="180" y="310" width="150" height="50" rx="8"></rect><rect x="360" y="310" width="150" height="50" rx="8"></rect><rect x="540" y="310" width="150" height="50" rx="8"></rect><rect x="720" y="310" width="150" height="50" rx="8"></rect></g><g fill="currentColor" text-anchor="middle"><text x="255" y="340" font-weight="700">24V 开关量</text><text x="435" y="340" font-weight="700">4-20mA / 0-10V</text><text x="615" y="340" font-weight="700">RS-485 Modbus RTU</text><text x="795" y="340" font-weight="700">CAN 总线</text><text x="450" y="392" font-size="11" opacity=".75">一对线一个信号，或一条总线挂多台设备</text></g><g stroke="currentColor" stroke-width="1.4"><line x1="100" y1="290" x2="100" y2="270" marker-end="url(#ic-arr)"></line><line x1="100" y1="150" x2="100" y2="130" marker-end="url(#ic-arr)"></line></g><text x="108" y="284" fill="currentColor" font-size="11">数据往上</text><text x="108" y="144" fill="currentColor" font-size="11">数据往上</text>',15)])]))]),t[2]||(t[2]=e('<h3 id="现场总线-vs-工业以太网" tabindex="-1">现场总线 vs 工业以太网 <a class="header-anchor" href="#现场总线-vs-工业以太网" aria-label="Permalink to &quot;现场总线 vs 工业以太网&quot;">​</a></h3><p><strong>现场总线（Fieldbus）</strong>：用一条总线（一对或几对线）把多个现场设备串起来，取代&quot;一个信号一对线&quot;的老做法。Modbus RTU、CAN、Profibus、DeviceNet 都属于这类。它们物理层各有各的规定（RS-485、CAN 差分等），速度一般是 kbit/s 到几 Mbit/s。</p><p><strong>工业以太网（Industrial Ethernet）</strong>：沿用以太网的网线、接口和交换机，在上面跑工业协议。Modbus TCP、Profinet、EtherNet/IP、EtherCAT 是例子。优点是速度快（100 Mbit/s 起）、一张网能和办公网络打通、IT 人员熟悉；缺点是需要考虑实时性、网络安全，设备也更贵。</p><table tabindex="0"><thead><tr><th>对比项</th><th>现场总线</th><th>工业以太网</th></tr></thead><tbody><tr><td>典型物理层</td><td>RS-485、CAN</td><td>双绞线网线（RJ45）、光纤</td></tr><tr><td>典型速度</td><td>9.6 kbit/s ~ 几 Mbit/s</td><td>100 Mbit/s ~ 1 Gbit/s</td></tr><tr><td>节点数</td><td>几个到几十个</td><td>受交换机和 IP 限制，规模更大</td></tr><tr><td>接线</td><td>手拉手总线，要终端电阻</td><td>星形，接交换机</td></tr><tr><td>新项目趋势</td><td>逐渐被取代，但存量巨大</td><td>主流</td></tr></tbody></table><blockquote><p>现实中你面对的永远是&quot;新旧混搭&quot;：贴片机用以太网，回流焊炉里的温控表用 RS-485，现场接近开关还是 24V 开关量。所以两边都要会。</p></blockquote><h3 id="协议地图-本目录的所有词条" tabindex="-1">协议地图：本目录的所有词条 <a class="header-anchor" href="#协议地图-本目录的所有词条" aria-label="Permalink to &quot;协议地图：本目录的所有词条&quot;">​</a></h3><p>下面把本目录（含还没写的计划词条，灰色虚线的是还没写）按&quot;层&quot;排好，每个一句话说明。</p><p><strong>物理层与基础（设备层）</strong></p><table tabindex="0"><thead><tr><th>词条</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/Encyclopedia/70-工业通信与自动化/传感器与执行器">传感器与执行器</a></td><td>设备层的&quot;眼睛和手&quot;，信号是 24V 开关量或 4–20 mA、0–10V</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a></td><td>一位一位地发字节的最古老通信方式，所有串口协议的基础</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/RS-232与RS-485">RS-232与RS-485</a></td><td>串口的两种电气标准：点对点短距离 vs 多点长距离</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/CAN总线">CAN总线</a></td><td>抗干扰强的多主总线，设备、汽车常用</td></tr></tbody></table><p><strong>控制设备（控制层）</strong></p><table tabindex="0"><thead><tr><th>词条</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a></td><td>车间里最常见的控制器，周期性地&quot;读输入—算逻辑—写输出&quot;</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/PLC梯形图编程">PLC梯形图编程</a></td><td>PLC 最常用的编程语言，长得像继电器电路图</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/HMI">HMI</a></td><td>触摸屏，操作员与 PLC 之间的窗口</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/SCADA">SCADA</a></td><td>监控整条产线或整个车间的上位机系统</td></tr></tbody></table><p><strong>通信协议（控制层 / 信息层）</strong></p><table tabindex="0"><thead><tr><th>词条</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>（含 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-RTU">Modbus-RTU</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>）</td><td>最简单、最通用的老牌协议，几乎所有设备都支持</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/西门子S7通信">西门子S7通信</a>、<a href="/Encyclopedia/70-工业通信与自动化/三菱MC协议">三菱MC协议</a>、<a href="/Encyclopedia/70-工业通信与自动化/欧姆龙FINS">欧姆龙FINS</a></td><td>三大日系/欧系 PLC 厂家的私有协议，读写 PLC 内存</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/Profinet">Profinet</a>、<a href="/Encyclopedia/70-工业通信与自动化/EtherNet-IP">EtherNet-IP</a></td><td>西门子阵营和罗克韦尔阵营的工业以太网</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/工业以太网">工业以太网</a></td><td>以太网在工业场景的总体介绍</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/OPC-DA">OPC-DA</a>、<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a></td><td>跨厂家的数据访问标准，旧的基于 Windows，新的跨平台且安全</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/MQTT">MQTT</a></td><td>轻量的&quot;发布/订阅&quot;消息协议，适合上云和 IoT</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/SECS-GEM">SECS-GEM</a></td><td>半导体行业的设备通信标准，部分电子厂的设备也用</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/IPC-CFX">IPC-CFX</a>、<a href="/Encyclopedia/70-工业通信与自动化/IPC-Hermes">IPC-Hermes</a></td><td>电子组装行业标准：设备上报数据（CFX）、板子在设备间传递（Hermes）</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/条码与二维码">条码与二维码</a>、<a href="/Encyclopedia/70-工业通信与自动化/RFID">RFID</a></td><td>给产品和物料&quot;贴身份证&quot;，是数据采集的重要入口</td></tr><tr><td><a href="/Encyclopedia/70-工业通信与自动化/工业网络安全">工业网络安全</a></td><td>让这些协议不被攻击者利用</td></tr></tbody></table><h3 id="学习顺序-入门路径" tabindex="-1">学习顺序（入门路径） <a class="header-anchor" href="#学习顺序-入门路径" aria-label="Permalink to &quot;学习顺序（入门路径）&quot;">​</a></h3><p>不要从协议字典开始背。按下面顺序走，每一步都在上一步的基础上：</p><ol><li>先看本篇，建立全景。</li><li><strong>物理层</strong>：<a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a> → <a href="/Encyclopedia/70-工业通信与自动化/RS-232与RS-485">RS-232与RS-485</a>。这是理解 Modbus RTU 的前提。</li><li><strong>第一个完整协议</strong>：<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 系列（<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus数据模型与地址">Modbus数据模型与地址</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-RTU">Modbus-RTU</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>）。已写好，有可运行的动手实验。</li><li><strong>控制设备</strong>：<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a> → <a href="/Encyclopedia/70-工业通信与自动化/PLC梯形图编程">PLC梯形图编程</a> → <a href="/Encyclopedia/70-工业通信与自动化/传感器与执行器">传感器与执行器</a>。理解 Modbus 读写的&quot;对面&quot;到底是什么。</li><li><strong>人机与监控</strong>：<a href="/Encyclopedia/70-工业通信与自动化/HMI">HMI</a> → <a href="/Encyclopedia/70-工业通信与自动化/SCADA">SCADA</a>。</li><li><strong>PLC 厂家协议</strong>：<a href="/Encyclopedia/70-工业通信与自动化/西门子S7通信">西门子S7通信</a>、<a href="/Encyclopedia/70-工业通信与自动化/三菱MC协议">三菱MC协议</a>、<a href="/Encyclopedia/70-工业通信与自动化/欧姆龙FINS">欧姆龙FINS</a>（用到哪家学哪家）。</li><li><strong>工业以太网</strong>：<a href="/Encyclopedia/70-工业通信与自动化/工业以太网">工业以太网</a> → <a href="/Encyclopedia/70-工业通信与自动化/Profinet">Profinet</a> / <a href="/Encyclopedia/70-工业通信与自动化/EtherNet-IP">EtherNet-IP</a>。</li><li><strong>向上对接</strong>：<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a> → <a href="/Encyclopedia/70-工业通信与自动化/MQTT">MQTT</a>；电子制造再学 <a href="/Encyclopedia/70-工业通信与自动化/IPC-CFX">IPC-CFX</a>、<a href="/Encyclopedia/70-工业通信与自动化/SECS-GEM">SECS-GEM</a>。</li><li><strong>身份识别</strong>：<a href="/Encyclopedia/70-工业通信与自动化/条码与二维码">条码与二维码</a>、<a href="/Encyclopedia/70-工业通信与自动化/RFID">RFID</a>；最后看 <a href="/Encyclopedia/70-工业通信与自动化/工业网络安全">工业网络安全</a>。</li><li>回到业务：<a href="/Encyclopedia/80-电子制造业务/设备自动化/设备数据采集">设备数据采集</a>、<a href="/Encyclopedia/80-电子制造业务/设备自动化/SMT设备接口">SMT设备接口</a>、<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>。</li></ol><h2 id="逐步例子-一次温度读数是怎么走到-mes-的" tabindex="-1">逐步例子：一次温度读数是怎么走到 MES 的 <a class="header-anchor" href="#逐步例子-一次温度读数是怎么走到-mes-的" aria-label="Permalink to &quot;逐步例子：一次温度读数是怎么走到 MES 的&quot;">​</a></h2><p>场景：回流焊炉第 3 温区的热电偶（一种测温元件）要把温度送到 MES 的看板上。</p><table tabindex="0"><thead><tr><th>步骤</th><th>位置</th><th>发生什么</th><th>用的&quot;语言&quot;</th></tr></thead><tbody><tr><td>1</td><td>设备层</td><td>热电偶产生毫伏级电压，变送器放大成 4–20 mA（见 <a href="/Encyclopedia/70-工业通信与自动化/传感器与执行器">传感器与执行器</a>），比如 12 mA</td><td>模拟量电流</td></tr><tr><td>2</td><td>设备层→控制层</td><td>PLC 模拟量输入模块把 12 mA 转成一个整数，如 16384（参考 <a href="/Encyclopedia/70-工业通信与自动化/传感器与执行器">传感器与执行器</a> 的换算）</td><td>内部数字量</td></tr><tr><td>3</td><td>控制层</td><td>PLC 程序（<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a> 的扫描周期）把整数换算成 245.3 ℃，存到寄存器</td><td>PLC 内存</td></tr><tr><td>4</td><td>控制层</td><td>HMI 通过 Modbus 或厂家协议读出该寄存器，显示在炉子触摸屏上（<a href="/Encyclopedia/70-工业通信与自动化/HMI">HMI</a>）</td><td>如 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a></td></tr><tr><td>5</td><td>控制层→信息层</td><td>SCADA/网关用 OPC UA 或 Modbus TCP 再读一遍，存入历史库（<a href="/Encyclopedia/70-工业通信与自动化/SCADA">SCADA</a>）</td><td><a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a></td></tr><tr><td>6</td><td>信息层</td><td>MES 在看板上显示，并把温度和批次、工单关联存入数据库</td><td>数据库 / 接口</td></tr></tbody></table><p>可以看出：<strong>同一个数据在不同层以不同形式出现</strong>，每次转换都是一个可能出错的地方（量程设错、小数位错、地址错位）。排查&quot;MES 里温度不对&quot;时，就从下往上一层层核对。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>本篇的实验不需要设备，做一件很有用的事：<strong>为你们厂的一台设备画一张&quot;通信档案&quot;</strong>。</p><ol><li>选一台设备（比如回流焊炉、贴片机或 AOI）。</li><li>打开它的说明书（或问设备厂），填下面的表。</li></ol><table tabindex="0"><thead><tr><th>问题</th><th>答案（你填）</th></tr></thead><tbody><tr><td>设备型号、PLC 型号</td><td></td></tr><tr><td>它对外提供什么物理接口？RS-232 / RS-485 / 网口？</td><td></td></tr><tr><td>网口还是串口？默认 IP 或串口参数（波特率、数据位、校验、停止位）？</td><td></td></tr><tr><td>支持哪些协议？Modbus / OPC UA / 厂家私有 / SECS-GEM / IPC-CFX？</td><td></td></tr><tr><td>有没有寄存器地址表或点位表？</td><td></td></tr><tr><td>目前谁在读它？MES、SCADA、还是没人读？</td><td></td></tr></tbody></table><ol start="3"><li>对照本篇的协议地图，找到该协议的词条去学。</li><li>有了协议和地址表，再去做 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 里的动手实验的&quot;换一个真实地址&quot;练习。</li></ol><p>常用 TCP 端口（便于你在防火墙或抓包里认出它们）：Modbus TCP 是 502，MQTT 是 1883，OPC UA 是 4840（来自维基百科端口列表）。EtherNet/IP 的 I/O 数据用 2222，S7 通信用 102（ISO-TSAP）。后两项在该列表中有记录，但对应到具体产品的说法来自模型知识，使用前以官方文档为准。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>最可能的原因</th></tr></thead><tbody><tr><td>说不清设备到底&quot;支持什么协议&quot;</td><td>把&quot;物理接口&quot;和&quot;协议&quot;混为一谈：RS-485 是电气标准，Modbus RTU 才是协议；网口也不等于 Modbus TCP</td></tr><tr><td>读到的数是对的但小数位不对</td><td>设备把 245.3 存成 2453（放大 10 倍），没按手册换算</td></tr><tr><td>以太网设备能 ping 通，协议却连不上</td><td>端口被防火墙拦、设备连接数满、协议没启用</td></tr><tr><td>老设备只有 RS-232，电脑没有串口</td><td>用 USB 转串口线，或串口服务器（把串口转成网口）</td></tr><tr><td>想&quot;一步到位&quot;全换成新协议</td><td>存量设备不能换；用网关做协议转换，别为统一而换设备</td></tr><tr><td>协议太多学不过来</td><td>按入门路径走，用到一个学一个；原理（帧、地址、功能码）是相通的</td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><p><strong>业务视角</strong>：工业通信决定了&quot;数据采集的覆盖率和实时性&quot;。能自动采集的设备越多，MES 越不依赖人工录入，追溯越准、<a href="/Encyclopedia/80-电子制造业务/MES/OEE">OEE</a> 越可信。设备联网的成本（买网关、买协议授权、停线调试）要和收益一起算。</p><p><strong>技术视角</strong>：作为信息化开发者，你通常处在&quot;信息层&quot;。你关心的是：设备能提供什么接口、数据怎么映射成业务字段、断线怎么重连、时间戳怎么对齐。你不需要写 PLC 程序，但要看得懂点位表和梯形图，这样才能和自动化工程师无障碍沟通。</p><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>温控表通过 RS-485 接到 PLC，PLC 再通过网线接到 MES 服务器。这条链路里有哪几种通信？ <strong>答</strong>：温控表—PLC 是 RS-485（可能跑 Modbus RTU）；PLC—MES 是以太网（Modbus TCP、S7 或 OPC UA 等）。两段物理层、协议都可以不同，PLC 起&quot;翻译&quot;作用。</li><li>RS-485 是协议吗？ <strong>答</strong>：不是，是电气标准（线怎么接、电压怎么定）。跑在它上面的协议才是 Modbus RTU 等。</li><li>为什么信息层不用 4–20 mA？ <strong>答</strong>：信息层要传结构化的大量数据（订单、批次、报警），模拟量一对线只能传一个数值。</li><li>现场总线和工业以太网各举两个例子。 <strong>答</strong>：现场总线：Modbus RTU、CAN；工业以太网：Modbus TCP、Profinet。</li><li>一台老设备只有 RS-232，要接进以太网，有哪些做法？ <strong>答</strong>：串口服务器（RS-232 转网口，设备作为虚拟串口或 TCP 透传）、协议网关，或用工控机采集后再转发。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工业通信分三层：设备层（模拟量、开关量、总线）、控制层（PLC、HMI、SCADA）、信息层（MES、OPC UA、MQTT）。</li><li>现场总线和工业以太网并存，物理接口不等于协议。</li><li>同一数据在不同层形式不同，排查从下往上。</li><li>按&quot;串口 → RS-485 → Modbus → PLC → HMI/SCADA → 工业以太网 → OPC UA/MQTT&quot;的顺序学最顺。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/80-电子制造业务/地图/ISA-95">ISA-95</a>、<a href="/Encyclopedia/80-电子制造业务/地图/电子制造信息系统全景图">电子制造信息系统全景图</a>、<a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a>、<a href="/Encyclopedia/70-工业通信与自动化/RS-232与RS-485">RS-232与RS-485</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a>、<a href="/Encyclopedia/70-工业通信与自动化/SCADA">SCADA</a>、<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a>、<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>维基百科 Fieldbus：<a href="https://en.wikipedia.org/wiki/Fieldbus" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Fieldbus</a></li><li>维基百科 Industrial Ethernet：<a href="https://en.wikipedia.org/wiki/Industrial_Ethernet" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Industrial_Ethernet</a></li><li>TCP/UDP 端口列表：<a href="https://en.wikipedia.org/wiki/List_of_TCP_and_UDP_port_numbers" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/List_of_TCP_and_UDP_port_numbers</a></li></ul>',39))])}const C=r(i,[["render",n]]);export{y as __pageData,C as default};
